// ---------------------------------------------------------------------------
// Binary operations
// ---------------------------------------------------------------------------

macro_rules! binary_test {
    ($name:ident, $op:ident, $subdir:expr, $tol:expr) => {
        #[test]
        fn $name() {
            let test_name = stringify!($name);
            if !refs_available(test_name) {
                return;
            }
            let dir = ref_dir().join("binary").join($subdir);
            let a = load_input_n(&dir, 0);
            let b = load_input_n(&dir, 1);
            let expected = load_expected(&dir, test_name);
            let actual = a
                .$op(&b)
                .expect(concat!(stringify!($op), " should succeed"));
            assert_parity(test_name, &actual, &expected, $tol);
        }
    };
}

binary_test!(test_add_parity, add, "add", 1e-6);
binary_test!(test_sub_parity, sub, "sub", 1e-6);
binary_test!(test_mul_parity, mul, "mul", 1e-6);
binary_test!(test_div_parity, div, "div", 1e-4);
binary_test!(test_add_broadcast_parity, add, "add_broadcast", 1e-6);

