// ---------------------------------------------------------------------------
// Normalization (LayerNorm)
// ---------------------------------------------------------------------------

#[test]
fn test_layernorm_parity() {
    let test_name = "test_layernorm_parity";
    if !refs_available(test_name) {
        return;
    }
    let dir = ref_dir().join("norm").join("layernorm");
    let input = load_input(&dir);
    let expected = load_expected(&dir, test_name);

    // Load LayerNorm parameters from metadata.
    let meta_path = dir.join("metadata.json");
    let meta: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(&meta_path).expect("metadata.json should exist"),
    )
    .expect("valid JSON");

    let weight: Vec<f32> = meta["weight"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_f64().unwrap() as f32)
        .collect();
    let bias: Vec<f32> = meta["bias"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_f64().unwrap() as f32)
        .collect();
    let eps = meta["eps"].as_f64().unwrap_or(1e-5);

    let normalized_size = weight.len();
    let weight_t =
        DynTensor::from_vec(weight, vec![normalized_size], &Device::Cpu).expect("weight tensor");
    let bias_t =
        DynTensor::from_vec(bias, vec![normalized_size], &Device::Cpu).expect("bias tensor");

    // Manual layer norm: normalize last dim, then affine.
    let ln = nn_core::LayerNorm::new(weight_t, bias_t, eps).expect("valid LayerNorm");
    let actual = ln
        .forward(&input)
        .expect("layernorm forward should succeed");
    assert_parity(test_name, &actual, &expected, 1e-4);
}
